namespace SMSR.App.Mvp;

internal static class SmsrMcpInstructions
{
    public const string Text = """
        SMSR은 에이전트를 호출하지 않습니다. 계산, 짧은 검색, 질문·설명, 읽기 전용 확인, 상태 조회, 파일을 바꾸지 않는 명령은 아무것도 기록하지 마세요. 프로젝트 파일을 실제로 변경한 요청은 최종 응답 직전에 record_daily_activity를 정확히 한 번 호출해 요청별 고유 activityId, 짧은 작업 제목, 결과 요약, 변경 파일, 검증 결과와 산출물을 기록하세요. 같은 카드를 정정할 때만 activityId를 재사용하세요. 프롬프트·명령·도구 입력·출력 원문은 기록하지 마세요. 그래프는 사용자의 명시 요청 또는 현재 훅 컨텍스트가 허용한 복잡한 프로젝트 작업에만 사용하세요. 복잡도 판단이 모호하거나 한 곳의 작은 수정이면 그래프 없이 일일 활동만 기록하세요. 새 그래프는 저장소 폴더명을 projectId로 사용하고 첫 save_plan에서 workflowId를 생략하세요. 반환된 읽기 쉬운 workflowId는 해당 범위에서만 사용하고 일일 활동에도 연결하세요. 모든 계획 노드가 종료되면 범위를 닫으며, 이후 요청은 그 요청 자체가 다시 조건을 만족하지 않는 한 새 그래프를 만들지 마세요. 활성 그래프의 관련 후속 작업은 시작 전에 같은 workflowId의 형제 또는 새 최상위 노드로 추가하고 완료 노드와 dependsOn으로 연결하세요. SUCCESS 노드를 다시 열거나 변경하거나 하위 작업의 부모로 사용하지 마세요. 계획 저장 직후 첫 노드를 IN_PROGRESS로 기록하고 의미 있는 상태 변화는 즉시 record_event로 보내세요. 변화 없이 오래 실행할 때만 30초 이내 heartbeat를 사용하세요. 선행 노드는 SUCCESS 후 후행 노드를 시작하고 독립 작업만 병렬로 진행하세요. 이전 그래프 재개 요청은 list_workflows, get_plan, get_state를 사용하고 후보가 모호하면 사용자에게 선택을 요청하세요.
        """;
